def sort_count(a, buf, lo, hi):
    if hi - lo < 2:
        return 0
    mid = (lo + hi) // 2
    count = sort_count(a, buf, lo, mid) + sort_count(a, buf, mid, hi)
    i, j, k = lo, mid, lo
    while i < mid and j < hi:
        if a[i] <= a[j]:
            buf[k] = a[i]
            i += 1
        else:
            buf[k] = a[j]
            j += 1
            count += mid - i
        k += 1
    rest = a[i:mid] + a[j:hi]
    buf[k:hi] = rest
    a[lo:hi] = buf[lo:hi]
    return count


def count_inversions(nums):
    a = list(nums)
    return sort_count(a, [0] * len(a), 0, len(a))

