def sort_drops(a, buf, lo, hi, d):
    if hi - lo < 2:
        return 0
    mid = (lo + hi) // 2
    count = sort_drops(a, buf, lo, mid, d) + sort_drops(a, buf, mid, hi, d)
    i = lo
    for j in range(mid, hi):
        while i < mid and a[i] <= a[j] + d:
            i += 1
        count += mid - i
    buf[lo:hi] = sorted(a[lo:mid] + a[mid:hi])
    a[lo:hi] = buf[lo:hi]
    return count


def count_drops(nums, d):
    a = list(nums)
    return sort_drops(a, [0] * len(a), 0, len(a), d)

