static long sortDrops(int[] a, int[] buf, int lo, int hi, long d) {
    if (hi - lo < 2) return 0;
    int mid = (lo + hi) >>> 1;
    long count = sortDrops(a, buf, lo, mid, d) + sortDrops(a, buf, mid, hi, d);
    int i = lo;
    for (int j = mid; j < hi; j++) {
        while (i < mid && a[i] <= a[j] + d) i++;
        count += mid - i;
    }
    int l = lo, r = mid, k = lo;
    while (l < mid && r < hi) buf[k++] = a[l] <= a[r] ? a[l++] : a[r++];
    while (l < mid) buf[k++] = a[l++];
    while (r < hi) buf[k++] = a[r++];
    System.arraycopy(buf, lo, a, lo, hi - lo);
    return count;
}

static long countDrops(int[] nums, int d) {
    int[] a = nums.clone();
    return sortDrops(a, new int[a.length], 0, a.length, d);
}

